  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (347::BIGINT, 'Se ve que sabe mucho pero lamentablemente no comparte de la mejor manera ese conocimiento. Solo el 30% del tiempo de la clase lo dedica a la materia entonces la ve muy por encima. No se aprende mucho con él... Aproveche hacer los exámenes en grupo porque son algo largos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchos proyectos grupales']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, '3773e0901e7379e9e836b4a608175d251bec2ec284eebb1e402fe0951d1e7a02'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Aproveche las evaluaciones virtuales, y sus evaluaciones son algo extrañas, recicla trabajos pasado, para que pida a gente q ya lo llevo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-29T00:00:00+00:00'::TIMESTAMPTZ, '8d76dad4c6d2b37b36141c0ca7fe5779c7e0b22edd060eb7120a7101d1d7181a'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Clases cortas, quices y exámenes algunos repetidos, otros no, pero no son complicados. Aprovechar las evaluaciones virtuales y como profesor 10/10 es muy buena nota'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, '85995f4d1b1fd318986c972539ea8d0a31cf35036bcdbc1772b419f39be5be1a'::TEXT, ARRAY[1190]::BIGINT[]),
    (347::BIGINT, 'Habla mucho de problemas y opiniones personales, es cansado escucharlo porque habla mucha paja, no se presta demasiada atención, recicla examenes y quices.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-02-13T00:00:00+00:00'::TIMESTAMPTZ, '6f8863c6d0686726fab618fb769c759bdc615e705ac658715f96a66fb9b25860'::TEXT, ARRAY[1190]::BIGINT[]),
    (347::BIGINT, 'Es un profe bueno, pero no se le entiende. Todas sus clases son ejercicios viejos que pone y pone de nuevo, dice que ya todo eso está hecho pero no pone nada nuevo, casi no explica, el examen casi nunca es más difícil que lo que usualmente se ve en clase'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-09-16T00:00:00+00:00'::TIMESTAMPTZ, 'e381799e19b68df03fae86ebac6db770f489d4d96d547dcce09beef6da29c96c'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'Siempre se queja de otros temas en clases que no tienen que ver con el curso y apesar de que tengás los procedimientos correctos te pone un 0'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '876553be275b524cd86e341e8146d7f5d69b55896ff79c45cf78fc66305ba67e'::TEXT, ARRAY[1190]::BIGINT[]),
    (347::BIGINT, 'Es un buen profe, tiene mucha experiencia y siempre trata de mostrar a un estudiantes proyectos reales con los que está trabajando. Sus clases son semipresenciales, algunos quiz son virtuales y se puede hacer en pareja. Para el proyecto final se utiliza revit y twinmotion.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2024-06-02T00:00:00+00:00'::TIMESTAMPTZ, '909a196e397890e8e25ac0c1dd2679af8259ecb1c410c90f420e0a3e038f9ab5'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Es un profesor muy bueno! Explica los contenidos del curso bien; tiene bastante conocimiento y experiencia laboral (eso le da un enfoque de criterio ingenieril). Mi recomendación es que aprovechen ir a consulta si les cuestan algunos temas y llevar al día la materia. Es de los mejores profes :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2023-07-07T00:00:00+00:00'::TIMESTAMPTZ, '893e02b7eb7393aba05abed5eb4424f287ea4df3f1cf08b39e93a439dd4f1491'::TEXT, ARRAY[1188, 1182, 1190]::BIGINT[]),
    (347::BIGINT, 'Los ejercicios que se ven en clase tienen el mismo nivel de dificultad que los que entran en el examen, nunca te va a poner algo más difícil de lo que explicó. Siempre a disposición de ayudarlo a uno y de que todo quede claro. Lleve todo al día, practique mucho y el curso se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'f2c7d2fee1ad50cb6344df5172f0a6e3a62087d3dc828dc87e46741fb3c99f85'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'Lo que explica es lo que viene en el examen, las clases suelen ser extensas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-02-02T00:00:00+00:00'::TIMESTAMPTZ, '45b6fdec7ad106aa391ee8d84e720ae1538d8006d63817ae724becec788f0a08'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'No es excelente, pero tampoco malo. Las clases pueden llegar a ser MUY aburridas porque habla de cualquier cosa la mitad de la clase. No hace el curso más dificil de lo que debe ser y lo que se hace en clase es lo que sale en el examen. Sube la materia al tec digital por si llegar a faltar.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'de5e57cf0e63c0e9fe4957d0bfe519a06ce8ff3826e604bd1af6d66c45bfedd5'::TEXT, ARRAY[1190]::BIGINT[]),
    (347::BIGINT, 'Excelente profesor, no se dején engañar con la calificación que tiene acá la verdad es muy buen profe, sin embargo, aveces se desvia mucho del tema, pero es para hablar de temas de construcción, al final estos temas que menciona son bastante provechosos'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'd6601190eff463e026ea009dee29de6c2b78dba441f8101372d63e718acb5b79'::TEXT, ARRAY[1182, 1188]::BIGINT[]),
    (347::BIGINT, 'La verdad se ha adaptado bastante bien a la virtualidad, habla demasiado pero al menos está relacionado a la carrera, tomé los tres cursos con él y no es un mal profesor, además se nota que de verdad ejerce la profesión, ayudándonos a generar "criterio"'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '4c9dacb54558bc1ac06eb08e10065f79bc2a0486b6959e739c6c5307a10bd687'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Excelente profe Clases claras'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'db23cf6857da8030d4328861f91fb5551939d3f16fc49a5f878247452147dc96'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'Explica bien y sus clases son cortas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'b72bd9ed4ab49fb8b3112ccad73a784b76c107028ef428e30b5ca38bc4883e83'::TEXT, ARRAY[1190]::BIGINT[]),
    (347::BIGINT, 'El profe habla demasiado pero lo que dice es cultura general sobre construcción. Muy interesante y útil pero los examenes y quices son distintos a los que explica. Aún así no es nada complicado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '78e63f9ca8da819c5c49a45ab25b5789182d4610a65bc1f2df22a4d1d14eab9a'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Excelente en entorno virtual, para mí es muy buen profesor y da la materia clara.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, 'f45200f93a495bb2c8d591831b73ecb934b9dc7a6a307c35b0d2d585278bf6e6'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'Buena persona y profesional pero siempre se desvía del tema del cual habla. Suele centrarse mucho en que está haciendo en sus proyectos y no da la teoría de manera profunda, medio te dice que es y pasa. Se adaptó excelentemente a las clases virtuales.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'cff001527f052824e6892c292bd632ffa1f9ada68d2a2de7b9db80b72e523548'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Se adaptó muy bien a la modalidad virtual, sus clases son largas y siempre se desvía del tema, pero al final se le entiende con claridad los quices y exámenes son regulares y no dejó muchos para este semestre, practique con examenes de otros semestres y pasa super bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '353f41861d7532385a5a57ee0ca1a1f6ea76661cdef57ad735c2638d96f2d4f1'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'El profe se acomodó demasiado bien a la virtualización, siempre se preocupa porque se aprenda, pasa pendiente a las preguntas o a cualquier aclaración que pueda hacer. Es muy buena persona, califica de manera justa.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '7eda5862dc90a8e98c868fd084c0f88220bff5277d4881633ab584ad04385a11'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'buen profe, se adapto muy bien a la virtualización mejorando su forma de impartir lecciones'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '7e6df09e2c1453166466a64bb39a04bd22b2e13271f44621a0cd7a79559f15d1'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'Fácilmente uno de los profes mas buena nota que hay. Se preocupa por el estudiante genere buen criterio y aprenda de lo que se trata la carrera. Este curso le va a decir si enserio le gusta o no Construcción. No es un curso duro, pero hay que leer bastante.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '4d7cba2911c143c75f48ebf0e3abfd58804fc4a3b37d6618ec1fc03f14e678f6'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'De planos no se aprende nada. Los consejos laborales que da son muy interesantes. Exámenes y quices siempre son los mismos. El curso se pasa fácil teniendo los exámenes de semestres pasados'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'd4bda4a1fdd54f04685413b6584a537fd08143ddb76f9762ac64faa9b205e721'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-07-12T00:00:00+00:00'::TIMESTAMPTZ, '940c414d833907fd2486ad973e25ddf5c520f050c57254bab89638be68958df0'::TEXT, ARRAY[1199]::BIGINT[]),
    (347::BIGINT, 'Es una teja de profe, para el que realmente pone atención en clase es de mucho provecho ya que da muchos consejos para nuestra vida laboral. Quices fáciles, los exámenes no son nada del otro mundo, y el proyecto por lo general la maqueta. En si, es un curso para salir con buena nota. (Ama la teja A)'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '957b2a42864164e4c039e9d77c1c44a293f3db2d75d529a52324856e80d9c06f'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Clases cortas y entretenidas, echarle el ojo a muchos documentos, exámenes parecidos a semestres anteriores, quices fáciles si pones atención y repasas los apuntes (muy importante tomar apuntes). Si pudiese hacerle el amor a la teja asfáltica lo haría.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '415a3008545f24ae262c86ad21381e2880942ebb4d1011f3a2dd6c9b68533675'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'No sabe qué hacer con el curso en las primeras clases y pregunta cosas que no se vieron en clase.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '04dadf6b6353e103f957741e5fb6525ca537c8d7f65abe5adb723996700d9ab2'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'La verdad es que el curso no es nada del otro mundo, los quices a veces si son bastante específicos y en los informes le gusta que uno se enfoque mucho en la práctica, los exámenes siempre son iguales a los de semestres pasados, entonces son sencillos, dura bastante para entregar notas'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '619799e87aa88e8c012d6dc8746b10fb08a2ab7107d6876be9779d35c05a3bc3'::TEXT, ARRAY[1199, 1201]::BIGINT[]),
    (347::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '08be9be0fb18d55c7c297c28c5ac10a1dafba75f6c2261d9c6f4547f9019cfb5'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Como siempre sus quices son muy salidos. Casi que la clase la daba Eduardo, el técnico de laboratorio. Los informes tienen que estar muy bien hechos y sobre todo le gusta mucho un buen análisis enfocado a la construcción y no a los resultados de la práctica. Entrega notas en semana 50.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '57302b8bb2198ecb2870570c6a542ef2f5efcde0439defa1baea59db8ad54f92'::TEXT, ARRAY[1199, 1201]::BIGINT[]),
    (347::BIGINT, 'quices con materia que no se ve en clase, exámenes busque pasados porque si no le va a ir mal ya que no hace ejercicios de nada. Ama la teja asfáltica y siempre habla de eso, uno en realidad no aprende de interpretación de planos.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-31T00:00:00+00:00'::TIMESTAMPTZ, '0e254f391789df38ef7699aa706f612faace6a4838bd1e93934a6b278f6c801a'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Advertencia: no va a aprender nada de interpretación de planos entonces no ilusionarse. Siempre pasa lista y para hacer los exámenes es mejor estudiar de exámenes viejos. En los quices pregunta temas que no se vio en clase. Ama la teja asfáltica. Si hacen maqueta, no lo dejen a lo último.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Exámenes retadores']::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, '7a5f6c8f4d90d062518cb052657c140a1f6997597f4c04ee9bc87d68c0c1bee9'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'El profe es buena gente, pero las clases son demasiadoooooo aburridas, el mae solo habla acerca de sus obras y no explica absolutamente nada de lo que viene en los examenes, casi siempre hace las mismas evaluaciones y nunca cambia nada, pero bueno, el curso se pasa'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'af2ec65b525068b173d45cd748b8977733b83fd558781906514cca82cc47e221'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '92bc988d778642a7124eb57dc507285a0e25d20e0c477160623ea0460509abb4'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Habla demasiado de los "millones" que gana pero del curso poco o nada es de utilidad debería enfocarse en sus estudiantes como lo hace con el proyecto'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2017-11-06T00:00:00+00:00'::TIMESTAMPTZ, '718a2cd88dea5990c5c37854196e30398bed31143ca42d6abb7daf182a2fee2f'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2017-10-13T00:00:00+00:00'::TIMESTAMPTZ, '23506f29be5118436e386b11710dccb88908362e5b3473bf18d9af7ff80f97d4'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '8d7edc1af285702746c1c15cb68e9ccea23ff8f0f3388f36fa4e1c1eccdabf20'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Ve lo que es necesario y todo lo explica y aplica a lo que realmente se ve en la calle. Es bastante interesante y califica justo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '21767cd9225732b918c1f185c204a3e76bab21119f5f98fd9e64c0943ee6fe7c'::TEXT, ARRAY[1199]::BIGINT[]),
    (347::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'a0bd0ee6bed24d561a6eb4daa6f4b8636a6156185d2a608654aa8e40a7464770'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Si se desvía de la materia pero a mi parecer es más interesante e importante lo que cuenta de sus experiencias en la calle. Es casi el único que nos habla con claridad lo que nos vamos a topar en el trabajo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, '356f2512c7e7daceb4b7d9673c42447c58b9d6e6770b1c6d8d5433e920c5ca88'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Buen profesor, los ejercicios de la clase son muy parecidos a los del examen, nos cuenta cómo es su experiencia en la calle.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'ae59289b27b2814ad5c243ac659dfc4f9bdd3957fc7b14c8e4bd39f976b234d0'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'califica duro pero el examen es casi en parejas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '527b82e525191a653a36b7cf7786c3acd1429018b41ce9d65021544be4798f78'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'hace entretenida la clase, se desvía mucho del tema porque se la pasa hablando de su vida, pero habla de cosas interesantes. no da aspectos de calificación nada claros, por lo que algo fácil luego no lo es tanto'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Muchos proyectos grupales']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, '247269ef4c9f5f863e604757065e68b2dad276d605e797b3e8d0918673ba06c8'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'El mae es buen profe, habla mucho sobre su trabajo pero en lo personal eso no me molesta, todo lo contrario. Trabaja ejercicios de exámenes todo muy claro, se me hizo relativamente fácil.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '884507df3ab8e76d1a6226de89db8a13df75e7ef6d1a82699fa98d08c37f4a6a'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'Muy buen profesor, se trabajan muchos ejercicios de los temas durante la clase y si lel estudiante no entiende le explica con paciencia. Califica un poco duro pero no es como si el curso fuera facil de perder'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'c19ab67a9ee06d0cd91cd01f63d3901841971aacab85ad3f39fc55c5991a5dd5'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'ea83f10e4c2871bda8cca72ff41ad4d33f4da6d0c21db86c753eef9637596367'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'Profe que no inspira, solo pasa hablando paja, es pésimo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'aceec2db17d65501d15b43f4c2276babb1f5a475fcff74472e7d5f5fe335e3d9'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'Ayuda al estudiante, la materia se presenta con claridad y deja tareas y da ejemplos muuuy similares al examen, a mi parecer es un excelente profesor, y no importa si no estes llevando su curso esta dispuesto a ayudarte en lo que pueda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-19T00:00:00+00:00'::TIMESTAMPTZ, '9c3576cfb12e75054c396c92e35b0e94865007e359ff3ffd485e211deb75124e'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'No explica muy bien y da pocos ejemplos, hay que estudiar por fuera... El 80% de clase es escuchar lo genial que es como ingeniero y los proyectos que tiene'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '857138144064af7f877c2c959b735c0797fc0a93818a8b46f3b1a38d89a15931'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'No explica nada en clases pero es el único que las da. Hay que buscar por afuera la materia que sale en los examenes.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2015-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'a65160eb6b55cd0502eb5a880cc6eec3c699ce31fd49a584a1e66c966fbfe822'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-22T00:00:00+00:00'::TIMESTAMPTZ, '41964160f54892ac740024a01f9423891157a4f0e97844dd4c51758e6dc36f2f'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'En mi opinión es buen profesor, explica claro, da bastantes ejemplos, similares al examen, solamente da poco tiempo a la hora de realizar los exámenes, se interesa por que todos pasen, le gusta contar anécdotas que ayudarían en un futuro, en mi opinión buen profesor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'd81620f4e94c4bc15512cb684a34b49ee89e3777fecae30f9ed641a1cafc8e2b'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'f6adff61ad51e0447cf1f9c3e48ae604196c9e9212ab6580a88dbbb63715cf48'::TEXT, ARRAY[1188, 1182]::BIGINT[]),
    (347::BIGINT, 'No explica con claridad. Sin embargo, es el único que da ciertos cursos. El curso de estática es fácil, entonces no hay problema en llevarlo con él.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'e87637f6ab7f8d05d900725a6bad2b85c03ed865c224503c4fdd8f740dbad8d2'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'Profe realmente pésimo, no va a aprender absolutamente nada con él. Nunca da clases, sólo llega a hablar de sus problemas.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-04-07T00:00:00+00:00'::TIMESTAMPTZ, '14315ab27ddf45503b6bbce700aa5458c837b06f66e1694e4565ae1dfead1661'::TEXT, ARRAY[1182, 1190]::BIGINT[]),
    (347::BIGINT, 'mucha experiencia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-23T00:00:00+00:00'::TIMESTAMPTZ, 'f9684c0762a382a7b651535fd7cdd2ad71d95d2e1e6da0fc45496b62d5dac47f'::TEXT, ARRAY[1198]::BIGINT[]),
    (347::BIGINT, 'No explica mucho pero es entretenida la clase. Cuenta muchas anecdotas relacionadas con el curso. Y es sumamente sencillo pasar. Si usted se queda con él, se queda con cualquier otro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'f635826e59ec372fb1f4a9484759e06b6b5b1230b80657911ba0d4604b15a026'::TEXT, ARRAY[1198]::BIGINT[]),
    (347::BIGINT, 'En lugar de dar la clase para que tiene una cita con el psicologo, pasa hablando de tus problemas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'a990919da746e41374642ba74147fc39058d6bc18c3f66db20f79a436bf7ab30'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Habla de todo menos de la materia que corresponede.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-21T00:00:00+00:00'::TIMESTAMPTZ, '1d8f4d82f3587f32f6b9f139ceba25871ab28f539fbb47da9ab3b2c67870f7c2'::TEXT, ARRAY[1182, 1188]::BIGINT[]),
    (347::BIGINT, 'No es buen profesor. habla mucho y explica poco no da suficientes ejemplos etc.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-08T00:00:00+00:00'::TIMESTAMPTZ, '886012c32144dd657b55de07ba1f52fa160bbd78a7b899b7a423196138f8f3cc'::TEXT, ARRAY[1182, 1190]::BIGINT[]),
    (347::BIGINT, 'Nunca aprendí nada con él.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '820fc1d63370a90a69a686e371c1174f0c03cfef15a8d72efd75ecc2ad690614'::TEXT, ARRAY[1188]::BIGINT[]),
    (347::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'a3f51a46872f3f0964544b7a9d0c25e048491fb9b7739acfb75d598858452cac'::TEXT, ARRAY[1182, 1188]::BIGINT[]),
    (347::BIGINT, 'Su dominio en la materia es pauperrimo'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'c1ec2b5e415635d3ef09b25ad64aff288de4aa7bd9c3b345fee27ff51741fecb'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '3b450d7a37a1900117e04a2675d03a83db6456fcc5395aa88781fcd3df77c6d3'::TEXT, ARRAY[1190]::BIGINT[]),
    (347::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '7acf3804d1803a42407cfc4fc06847ee479ad31ec689a14ad410891f1b3c7480'::TEXT, ARRAY[1182]::BIGINT[]),
    (347::BIGINT, 'Explica con ejemplos muy fáciles y creo que deja mucho sin enseñar, ademas pierde mucho tiempo hablando paja sobre sus conflictos legales'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'b5a39265de3744333b7c8c9c9b95927918f3428a9e62739243dd738e8c556a60'::TEXT, ARRAY[1182]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
